interface Greeter { String greet(String name); }
class EnglishGreeter implements Greeter {
    public String greet(String name) { return "Hello, " + name; }
}

Greeter g = new EnglishGreeter();
System.out.println(g.greet("Ala"));

class DelegatingHandler implements InvocationHandler {
    private final Object target;
    DelegatingHandler(Object target) { this.target = target; }
    public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
        return method.invoke(target, args);
    }
}

Greeter real = new EnglishGreeter();
Greeter proxy = (Greeter) Proxy.newProxyInstance(
    Greeter.class.getClassLoader(),
    new Class<?>[] { Greeter.class },
    new DelegatingHandler(real));
System.out.println(proxy.greet("Ala")); // Hello, Ala

class LoggingHandler implements InvocationHandler {
    private final Object target;
    LoggingHandler(Object t) { target = t; }
    public Object invoke(Object p, Method m, Object[] a) throws Throwable {
        System.out.println("Wywolanie: " + m.getName() + " z argumentami: " + Arrays.toString(a));
        return m.invoke(target, a);
    }
}

public Object invoke(Object p, Method m, Object[] a) throws Throwable {
    System.out.println("Wywolanie: " + m.getName());
    Object result = m.invoke(target, a);
    System.out.println("Wynik: " + result);
    return result;
}

public Object invoke(Object p, Method m, Object[] a) throws Throwable {
    long start = System.nanoTime();
    try {
        return m.invoke(target, a);
    } finally {
        System.out.println((System.nanoTime() - start) / 1_000_000 + " ms");
    }
}

