class CountingHandler implements InvocationHandler {
    private final Object target;
    private final Map<String, Integer> callCounts = new HashMap<>();
    CountingHandler(Object t) { target = t; }
    public Object invoke(Object p, Method m, Object[] a) throws Throwable {
        callCounts.merge(m.getName(), 1, Integer::sum);
        return m.invoke(target, a);
    }
    Map<String, Integer> getCallCounts() { return callCounts; }
}

class CachingHandler implements InvocationHandler {
    private final Object target;
    private final Map<Object, Object> cache = new HashMap<>();
    CachingHandler(Object t) { target = t; }
    public Object invoke(Object p, Method m, Object[] a) throws Throwable {
        Object key = a[0];
        if (cache.containsKey(key)) return cache.get(key);
        Object result = m.invoke(target, a);
        cache.put(key, result);
        return result;
    }
}

public Object invoke(Object p, Method m, Object[] a) throws Throwable {
    Throwable last = null;
    for (int i = 0; i < 3; i++) {
        try {
            return m.invoke(target, a);
        } catch (InvocationTargetException e) {
            last = e.getCause();
        }
    }
    throw last;
}

