class MetricsHandler implements InvocationHandler {
    private final Object target;
    private final Map<String, long[]> stats = new HashMap<>();
    public Object invoke(Object p, Method m, Object[] a) throws Throwable {
        long start = System.nanoTime();
        try { return m.invoke(target, a); }
        finally {
            long elapsed = System.nanoTime() - start;
            stats.computeIfAbsent(m.getName(), k -> new long[2]);
            stats.get(m.getName())[0]++;
            stats.get(m.getName())[1] += elapsed;
        }
    }
    void printReport() {
        stats.forEach((name, s) -> System.out.printf("%s | %d | %d us%n", name, s[0], s[1] / s[0] / 1000));
    }
}

class CircuitBreakerHandler implements InvocationHandler {
    private final Object target;
    private int consecutiveFailures = 0;
    private long openedAt = -1;
    private static final long COOLDOWN_MS = 2000;
    public Object invoke(Object p, Method m, Object[] a) throws Throwable {
        if (openedAt >= 0 && System.currentTimeMillis() - openedAt < COOLDOWN_MS) {
            throw new IllegalStateException("Circuit OPEN");
        }
        try {
            Object result = m.invoke(target, a);
            consecutiveFailures = 0;
            openedAt = -1;
            return result;
        } catch (InvocationTargetException e) {
            consecutiveFailures++;
            if (consecutiveFailures >= 3) openedAt = System.currentTimeMillis();
            throw e.getCause();
        }
    }
}

