class CompositeHandler implements InvocationHandler {
    private final Object target;
    private final List<Consumer<Method>> beforeHooks = new ArrayList<>();
    void addHook(Consumer<Method> hook) { beforeHooks.add(hook); }
    public Object invoke(Object p, Method m, Object[] a) throws Throwable {
        for (Consumer<Method> hook : beforeHooks) hook.accept(m);
        return m.invoke(target, a);
    }
}

