// TABLICE INTERFEJSOW - proba wpisania tam RealPaymentService.class dalaby blad kompilacji
// (Class<?>[] przyjmie to skladniowo, ale w runtime Proxy rzuci IllegalArgumentException,
// bo RealPaymentService nie jest interfejsem). Powod: mechanizm dziala przez WYGENEROWANIE
// nowej klasy, ktora IMPLEMENTUJE podane interfejsy (Java pozwala implementowac wiele
// interfejsow, ale dziedziczyc tylko z JEDNEJ klasy) - Proxy nie potrafi 'podszyc sie'
// pod klase konkretna, bo nie ma jak wygenerowac podklasy samym API jezyka. Prawdziwy
// framework (Spring AOP) w takiej sytuacji uzywa CGLIB/ByteBuddy - biblioteki generujace
// BAJTKOD w locie, tworzace PRAWDZIWA PODKLASE RealPaymentService (dziedziczenie, nie
// implementacja interfejsu), przesłaniajaca kazda niefinalna metode wlasnym kodem
// delegujacym do MethodInterceptora - stad wymog, by klasy proxowane przez CGLIB nie byly final.

long startDirect = System.nanoTime();
for (int i = 0; i < 200_000; i++) real.greet("x");
long directTime = System.nanoTime() - startDirect;

long startProxy = System.nanoTime();
for (int i = 0; i < 200_000; i++) proxy.greet("x");
long proxyTime = System.nanoTime() - startProxy;

System.out.println("Narzut: " + ((proxyTime - directTime) * 100.0 / directTime) + "%");
// Odniesienie: proxy dodaje narzut refleksji (Method.invoke) z Lesson16 PRZY KAZDYM wywolaniu,
// wiec narzut jest zauwazalny w petli - w kodzie produkcyjnym z mala liczba wywolan pomijalny.

@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.METHOD)
@interface Logged {}

static <T> T createAopProxy(T target, Class<T> interfaceType) {
    InvocationHandler h = (proxy, method, args) -> {
        Method implMethod = target.getClass().getMethod(method.getName(), method.getParameterTypes());
        boolean logged = implMethod.isAnnotationPresent(Logged.class);
        if (logged) System.out.println("PRZED: " + method.getName());
        Object result = method.invoke(target, args);
        if (logged) System.out.println("PO: " + method.getName());
        return result;
    };
    return (T) Proxy.newProxyInstance(interfaceType.getClassLoader(), new Class<?>[]{interfaceType}, h);
}
